class BangunAlarm {
  BangunAlarm({
    required this.id,
    required this.label,
    required this.hour,
    required this.minute,
    this.repeatMode = RepeatMode.once,
    List<int>? days,
    this.enabled = true,
    this.challengeKind = ChallengeKind.math,
    this.mathProblems = 4,
    List<String>? scanTargets,
    this.toneKind = ToneKind.builtin,
    this.tone = BuiltInTone.morningBricks,
    this.filePath,
    this.fileLabel,
    this.spotifyUrl,
    this.volume = 0.8,
    required this.createdAt,
  }) : days = days ?? const [1, 2, 3, 4, 5, 6, 7],
       scanTargets = scanTargets ?? const [];

  final int id;
  final String label;
  final int hour;
  final int minute;
  final RepeatMode repeatMode;
  final List<int> days; // ISO weekday: 1=Mon ... 7=Sun
  bool enabled;
  final ChallengeKind challengeKind;
  final int mathProblems; // 3 / 5 / 7
  final List<String> scanTargets;
  final ToneKind toneKind;
  final BuiltInTone tone;
  final String? filePath;
  final String? fileLabel;
  final String? spotifyUrl;
  double volume; // 0..1, enforced min by scheduler.
  final DateTime createdAt;

  /// Next ringing time strictly after [now0].
  DateTime nextOccurrence([DateTime? now0]) {
    final from = now0 ?? DateTime.now();
    final today = DateTime(from.year, from.month, from.day, hour, minute, 0);
    switch (repeatMode) {
      case RepeatMode.once:
      case RepeatMode.daily:
        if (today.isAfter(from)) return today;
        return today.add(const Duration(days: 1));
      case RepeatMode.weekly:
        final set = days.toSet();
        for (var i = 0; i < 7; i++) {
          final t = today.add(Duration(days: i));
          if (t.isAfter(from) && set.contains(t.weekday)) return t;
        }
        // No weekday selected (lerp guard): behave like a one-shot.
        return today.isAfter(from) ? today : today.add(const Duration(days: 1));
    }
  }

  String toneName() => switch (toneKind) {
    ToneKind.builtin => tone.title,
    ToneKind.file => fileLabel ?? filePath?.split('/').last ?? 'Custom file',
    ToneKind.spotify => 'Spotify link',
  };

  String challengeLabel() => switch (challengeKind) {
    ChallengeKind.math => '🧮 Math × $mathProblems',
    ChallengeKind.scan => '📷 Scan ${scanTargets.firstOrNull ?? "object"}',
    ChallengeKind.mix => '🔀 Pick at ring',
  };

  Map<String, dynamic> toJson() => {
    'id': id,
    'label': label,
    'hour': hour,
    'minute': minute,
    'repeatMode': repeatMode.name,
    'days': days,
    'enabled': enabled,
    'challengeKind': challengeKind.name,
    'mathProblems': mathProblems,
    'scanTargets': scanTargets,
    'toneKind': toneKind.name,
    'tone': tone.name,
    'filePath': filePath,
    'fileLabel': fileLabel,
    'spotifyUrl': spotifyUrl,
    'volume': volume,
    'createdAt': createdAt.millisecondsSinceEpoch,
  };

  factory BangunAlarm.fromJson(Map<String, dynamic> json) {
    T named<T extends Enum>(List<T> values, String? name, T fallback) =>
        values.firstWhereOrNull((v) => v.name == name) ?? fallback;
    return BangunAlarm(
      id: (json['id'] as num).toInt(),
      label: json['label'] as String? ?? 'Alarm',
      hour: (json['hour'] as num).toInt(),
      minute: (json['minute'] as num).toInt(),
      repeatMode: named(
        RepeatMode.values,
        json['repeatMode'] as String?,
        RepeatMode.once,
      ),
      days: ((json['days'] as List?) ?? const [])
          .map((e) => (e as num).toInt())
          .toList(),
      enabled: json['enabled'] as bool? ?? true,
      challengeKind: named(
        ChallengeKind.values,
        json['challengeKind'] as String?,
        ChallengeKind.math,
      ),
      mathProblems: (json['mathProblems'] as num?)?.toInt() ?? 4,
      scanTargets: ((json['scanTargets'] as List?) ?? const [])
          .map((e) => e as String)
          .toList(),
      toneKind: named(
        ToneKind.values,
        json['toneKind'] as String?,
        ToneKind.builtin,
      ),
      tone: named(
        BuiltInTone.values,
        json['tone'] as String?,
        BuiltInTone.morningBricks,
      ),
      filePath: json['filePath'] as String?,
      fileLabel: json['fileLabel'] as String?,
      spotifyUrl: json['spotifyUrl'] as String?,
      volume: (json['volume'] as num?)?.toDouble() ?? 0.8,
      createdAt: json['createdAt'] != null
          ? DateTime.fromMillisecondsSinceEpoch((json['createdAt'] as num).toInt())
          : DateTime.now(),
    );
  }

  BangunAlarm copyWith({
    String? label,
    int? hour,
    int? minute,
    RepeatMode? repeatMode,
    List<int>? days,
    bool? enabled,
    ChallengeKind? challengeKind,
    int? mathProblems,
    List<String>? scanTargets,
    ToneKind? toneKind,
    BuiltInTone? tone,
    String? filePath,
    String? fileLabel,
    String? spotifyUrl,
    double? volume,
  }) {
    return BangunAlarm(
      id: id,
      label: label ?? this.label,
      hour: hour ?? this.hour,
      minute: minute ?? this.minute,
      repeatMode: repeatMode ?? this.repeatMode,
      days: days ?? this.days,
      enabled: enabled ?? this.enabled,
      challengeKind: challengeKind ?? this.challengeKind,
      mathProblems: mathProblems ?? this.mathProblems,
      scanTargets: scanTargets ?? this.scanTargets,
      toneKind: toneKind ?? this.toneKind,
      tone: tone ?? this.tone,
      filePath: filePath ?? this.filePath,
      fileLabel: fileLabel ?? this.fileLabel,
      spotifyUrl: spotifyUrl ?? this.spotifyUrl,
      volume: volume ?? this.volume,
      createdAt: createdAt,
    );
  }

  /// Same alarm with a fresh unique id (used when a duplicate collides).
  BangunAlarm copyWithId(int newId) {
    return BangunAlarm(
      id: newId,
      label: label,
      hour: hour,
      minute: minute,
      repeatMode: repeatMode,
      days: days,
      enabled: enabled,
      challengeKind: challengeKind,
      mathProblems: mathProblems,
      scanTargets: scanTargets,
      toneKind: toneKind,
      tone: tone,
      filePath: filePath,
      fileLabel: fileLabel,
      spotifyUrl: spotifyUrl,
      volume: volume,
      createdAt: createdAt,
    );
  }
}

/// Wake statistics persisted with the alarm store.
class WakeStats {
  WakeStats({
    this.totalWins = 0,
    this.mathWins = 0,
    this.scanWins = 0,
    this.currentStreak = 0,
    this.bestStreak = 0,
    Map<String, int>? winsByDay,
  }) : winsByDay = winsByDay ?? {};

  int totalWins;
  int mathWins;
  int scanWins;
  int currentStreak;
  int bestStreak;
  final Map<String, int> winsByDay; // yyyy-mm-dd -> wins

  void record(ChallengeKind kind) {
    totalWins++;
    if (kind == ChallengeKind.math || kind == ChallengeKind.mix) mathWins++;
    if (kind == ChallengeKind.scan || kind == ChallengeKind.mix) scanWins++;
    final k = todayKey();
    winsByDay[k] = (winsByDay[k] ?? 0) + 1;
    recompute();
  }

  void recompute() {
    final days =
        winsByDay.keys
            .map((k) => DateTime.tryParse(k))
            .whereType<DateTime>()
            .toList()
          ..sort();
    // Best consecutive run.
    var best = 0;
    var run = 0;
    for (var i = 0; i < days.length; i++) {
      final gap = i == 0 ? null : days[i].difference(days[i - 1]).inDays;
      run = (gap == null || gap == 1) ? run + 1 : 1;
      if (run > best) best = run;
    }
    bestStreak = best;
    // Current streak counts back from today (or yesterday if today not yet).
    final today = DateTime.now();
    final todayKeyStr = todayKey(today);
    final yesterdayKeyStr = todayKey(today.subtract(const Duration(days: 1)));
    var streak = 0;
    var cursor = winsByDay.containsKey(todayKeyStr)
        ? today
        : winsByDay.containsKey(yesterdayKeyStr)
        ? today.subtract(const Duration(days: 1))
        : null;
    while (cursor != null && winsByDay.containsKey(todayKey(cursor))) {
      streak++;
      cursor = cursor.subtract(const Duration(days: 1));
    }
    currentStreak = streak;
  }

  Map<String, dynamic> toJson() => {
    'totalWins': totalWins,
    'mathWins': mathWins,
    'scanWins': scanWins,
    'currentStreak': currentStreak,
    'bestStreak': bestStreak,
    'winsByDay': winsByDay,
  };

  factory WakeStats.fromJson(Map<String, dynamic> json) => WakeStats(
    totalWins: (json['totalWins'] as num?)?.toInt() ?? 0,
    mathWins: (json['mathWins'] as num?)?.toInt() ?? 0,
    scanWins: (json['scanWins'] as num?)?.toInt() ?? 0,
    currentStreak: (json['currentStreak'] as num?)?.toInt() ?? 0,
    bestStreak: (json['bestStreak'] as num?)?.toInt() ?? 0,
    winsByDay: ((json['winsByDay'] as Map<String, dynamic>?) ?? const {})
        .map((k, v) => MapEntry(k, (v as num).toInt())),
  );
}
